INSERT INTO public.registration_terms_documents(version,document)
VALUES ('2026-09-02.1', $terms${"version":"2026-09-02.1","effectiveDate":"2 September 2026","title":"Terms of Service","summary":"{{site_name}} connects drivers and car owners. You must independently check the other member and their information before paying, handing over a vehicle or starting work. Platform-history approval is not identity verification, insurance or a guarantee of safety or honesty.","sections":[{"title":"1. The platform's role","paragraphs":["{{site_name}} provides listings, profiles, messaging and support to help drivers and car owners find each other in Kenya. We are not a party to members' vehicle rental, employment or other working arrangements, and do not take possession or control of vehicles. We are not the driver, vehicle owner, insurer, guarantor or agent of either member. Contact the platform through {{support_email}} or {{support_phone}}."]},{"title":"2. Accounts and accurate information","paragraphs":["You must be at least 18, able to enter into a binding agreement and authorised to use or list any vehicle concerned. Give accurate, current information, protect your account and promptly correct material errors. Do not impersonate someone, submit false platform history, hide known vehicle defects, misrepresent insurance or share material you have no right to share."]},{"title":"3. Limited review — no KYC or guarantee","paragraphs":["We do not carry out KYC identity verification. Our driver verification feature is limited to reviewing submitted ride-hailing platform history. We cannot authenticate all member statements or documents. Approval of history or a listing, ratings, badges, availability labels and sponsored placement do not certify identity, a driving licence, criminal background, vehicle ownership, roadworthiness, insurance, platform registration or future conduct. Uploaded material may be incomplete, outdated or misleading. You must not treat a review or badge as a recommendation or a promise that a member is safe or suitable."]},{"title":"4. Checks before paying or handing over a vehicle","paragraphs":["Each member is responsible for independently checking the other party and all information they rely on. Owners should check the intended driver's identity, current licence and other legally required qualifications, experience and right to drive the vehicle for its proposed use. Drivers should check the owner's identity and authority to provide the vehicle, its condition, documents, insurance and suitability for the intended work. Verify cover, permitted drivers and commercial use directly with the insurer where appropriate; do not rely only on an uploaded image or profile label.","Meet safely, inspect the vehicle together, record its condition and agree written terms before payment or handover. Address targets or rent, deposits, authorised use, servicing, fuel, fines, accidents, damage, theft, insurance excess, termination and return of the vehicle. Do not proceed if checks are incomplete or something appears suspicious. Carry out checks lawfully and privately: do not upload identity cards, driving licences or logbooks to this platform."]},{"title":"5. Member arrangements, payments and damage","paragraphs":["Rental payments, deposits and working arrangements are agreed directly between members. {{site_name}} does not hold these funds in escrow, guarantee payment or provide vehicle insurance. Responsibility for vehicle damage, accidents, theft, misuse, unpaid amounts or other loss must be determined between the responsible parties, insurers and, where necessary, the relevant authorities under the law and their agreement. Merely connecting members does not make {{site_name}} responsible for a driver's damage to a vehicle or an owner's conduct."]},{"title":"6. Platform responsibility and legal rights","paragraphs":["To the extent permitted by applicable law, {{site_name}} is not liable for loss caused by a member's acts, omissions, false information or breach of their arrangement, including damage to or loss of a vehicle, injury, unpaid rent, deposits or lost income. This is not a blanket exclusion of the platform's own legal responsibility: nothing in these terms excludes liability for our fraud, wilful misconduct, negligence or any liability that cannot lawfully be excluded or limited. Your mandatory consumer, privacy and other statutory rights remain unaffected. The platform remains responsible for obligations the law places on its own services."]},{"title":"7. Conduct, support and disputes","paragraphs":["Fraud, threats, harassment, illegal activity and misleading listings or reports are prohibited. We may restrict content or accounts for breaches or safety concerns; contact support if you believe a decision is wrong. Support may assist communication and review available platform records, but does not act as a court, insurer, arbitrator or debt collector and cannot promise compensation or recovery of a vehicle or money. Report immediate danger or suspected crime to the relevant authorities, not only to platform support.","Connection and support conversations, including attachments, can remain available after a connection ends for continuity, safety and dispute handling. Authorised support staff may access or join a conversation for a support request, report or safety issue. Retention is subject to the Privacy Policy, lawful purposes and applicable data-protection rights; these terms do not authorise indefinite retention of every record."]},{"title":"8. Optional paid promotions","paragraphs":["Paid promotions are separate from members' rental arrangements. Review the price, duration, payment instructions and cancellation or refund terms on the saved quote before paying. Sponsored placement does not bypass moderation, guarantee enquiries or connections, or certify a member. No promotion payment authorises the platform to collect rent or deposits for another member. Mandatory consumer remedies continue to apply."]},{"title":"9. Acceptance, changes and applicable law","paragraphs":["At registration, you must actively accept these terms and acknowledge the Privacy Policy; the box is not selected for you. We record the terms version and the time your account is created with that acceptance. You can review and download a copy before signing up. You may correct your registration details or decline by not creating an account. Existing accounts are not recorded as having accepted this version unless they actually do so.","These terms are governed by Kenyan law. You retain access to courts, regulators and any remedies available under applicable law; contacting support first is encouraged but does not remove those rights. Material changes should be notified and any legally required fresh agreement obtained before they take effect. If a provision is unenforceable, the remaining provisions apply to the extent lawful."]}]}$terms$::jsonb);
